  // Retention
  "settings.retentionHint": "Hány biztonsági mentést tartson meg elemenként. Minden mentés után a restic a régebbi pillanatképeket ehhez a szabályhoz igazítva törli. Minden nulla = minden megtartása (ki).",
  "excludes.advisoryImmichDb": "Az Immich minden fénykép albumait, arcait és dátumait egy PostgreSQL adatbázisban tartja, amely egy teljesen külön konténerben fut, így ez a biztonsági mentés nem tartalmazza. Az innen való visszaállítás visszahozza a képeket, csak mindezek nélkül. A BombVault annak az adatbázisnak a konténeréről magától készít dumpot, amikor azt menti, ezért ellenőrizd, hogy benne van-e az ütemezésedben.",
  "excludes.advisoryNextcloudDb": "A Nextcloud a fiókjait, megosztásait és címkéit egy adatbázisban tartja, amely általában külön konténerben fut, így ez a biztonsági mentés nem tartalmazza. A fájlok visszajönnek, a megosztások nem. A BombVault annak az adatbázisnak a konténeréről magától készít dumpot, amikor azt menti, ezért ellenőrizd, hogy benne van-e az ütemezésedben.",
