  "excludes.presetHint.metadata": "Az alkalmazás által letöltött poszterek és képek. A metaadatok frissítése újra letölti őket, de itt vannak a saját feltöltött képeid is, és azok elvesznének. Ez a tétel először ki van kapcsolva.",
