  "rcloneRemote.heading": "SMB- vagy WebDAV-cél hozzáadása",
  "rcloneRemote.hint": "Windows- vagy Samba-megosztást, illetve WebDAV-kiszolgálót, például Nextcloudot ér el anélkül, hogy bármit csatolni kellene a gazdagépen. A restic nem javasolja, hogy a tároló csatolt CIFS-megosztáson legyen, ez az út pedig teljesen elkerüli a csatolást. A jelszót az rclone kapja meg, amely a saját formájában tárolja, így nyílt szövegként soha nem marad meg. Az NFS itt nem választható, mert sem a restic, sem az rclone nem kezeli: NFS esetén csatold az exportot az Unraidben, és állíts rá egy biztonsági mentési útvonalat.",
