  "dbdump.import": "Importálás friss adatbázisba",
  "dbdump.importConfirm": "Importálod ezt a {engine} {version} mentést ide: {container}? A BombVault leállítja a konténert, az adatmappáját félreteszi (megmarad, semmi nem törlődik), üres adatmappával elindítja a konténert, és importálja a mentést. Az adatbázist használó alkalmazások a mentés időpontjának állapotát látják majd.",
  "dbdump.importConfirmNoVersion": "Importálod ezt a {engine} mentést ide: {container}? A BombVault leállítja a konténert, az adatmappáját félreteszi (megmarad, semmi nem törlődik), üres adatmappával elindítja a konténert, és importálja a mentést. Az adatbázist használó alkalmazások a mentés időpontjának állapotát látják majd.",
  "dbdump.importNoVersion": "Ez a mentés nem rögzíti az adatbázisa verzióját. Az importálás meghiúsul, ha a kiszolgáló nem tudja olvasni.",
  "dbdump.importStops": "one=Az importálás idejére a BombVault a(z) {apps} alkalmazást is leállítja, utána pedig újraindítja. Ha az importálás a megkezdése után hiúsul meg, a régi adatok félretéve maradnak, az alkalmazás pedig leállítva.|other=Az importálás idejére a BombVault ezeket az alkalmazásokat is leállítja: {apps}. Utána újraindítja őket. Ha az importálás a megkezdése után hiúsul meg, a régi adatok félretéve maradnak, az alkalmazások pedig leállítva.",
  "dbdump.importDone": "Az adatbázis importálva.",
  "dbdump.importRefused.busy": "Épp másik biztonsági mentés vagy visszaállítás fut. Próbáld újra, ha befejeződött.",
  "dbdump.importRefused.notRunning": "Előbb indítsd el a konténert; az importáláshoz futó kiszolgáló kell.",
  "dbdump.importRefused.engineMismatch": "Ez a mentés más adatbázistípusból származik, mint amit a konténer futtat.",
  "dbdump.importRefused.noDataMount": "A BombVault nem éri el a konténer adatmappáját, így nem tudja biztonságosan félretenni. Importáld a mentést kézzel, ahogy a helyreállítási csomag leírja.",
  "dbdump.importRefused.version": "A kiszolgáló a(z) {server} verziót futtatja, a mentés {dump} verzióból való. Ehhez az importáláshoz használj {dump} vagy újabb verziójú képet.",
  "dbdump.importRefused.versionSameMajor": "A kiszolgáló a(z) {server} verziót futtatja, a mentés {dump} verzióból való. A MySQL és a MariaDB csak abba a főverzióba tölt be adatbázismentést, amelyből az készült, ezért ehhez az importáláshoz használj {dump} verziójú képet.",
  "dbdump.importRefused.damaged": "Ez a mentés sérült, nem importálható.",
