  "dbdump.restoreLiveWarn": "Ennek az adatbázisnak a fájljai futó kiszolgáló mellett másolódnak, ezért a visszaállított fájlok nem biztos, hogy tisztán indulnak. Ha nem, importáld az ezzel a biztonsági mentéssel készült adatbázis-mentést, amely lent szerepel.",
  "dbdump.restoreNoneWarn": "Ennek az adatbázisnak az adatmappája nincs a biztonsági mentésben. A visszaállítás üres adatbázissal hozza vissza a konténert; utána importálj egy mentést a lenti listából.",
  "dbdump.deleteConfirm": "Törlöd ezt az adatbázis-mentést? Eltávolítjuk a tárolóból (a hely felszabadításához futtasd a Prune-t a Beállításokban). Ez nem vonható vissza.",
