  "offsite.prune.title": "5 · Távoli nyesés",
  "offsite.prune.info": "Ez a lépés csak jelzi, mi történik, semmit nem állít be. Hogy ez a másolat nyesődik-e, azt a 4. lépés append-only beállítása és a Beállítások, Megőrzés alatti megtartási értékek döntik el. Ha egy append-only másolatot mégis nyesni akarsz, futtasd a restic forget --prune parancsot a tároló oldalán, akár saját ütemezéssel, akár úgy, hogy rövid időre felhúzol egy második, append-only nélküli REST-szervert, azon keresztül nyesel, majd leállítod.",
