  "recovery.foreignIntro": "Emeljen ki egyes konténereket, VM-eket, mappakészleteket vagy ZFS-adatkészleteket egy másik BombVault-példány biztonsági mentéseiből: csatlakozzon csak olvasásra, böngéssze a tartalmat, és állítsa vissza, amit kiválaszt. A másik repót csak olvassuk, ott semmi sem változik, és az Ön saját mentési beállításai érintetlenek maradnak.",
