  "anomaly.settings.title": "Anomáliák",
  "anomaly.settings.hint": "Egy elem minden biztonsági mentését összeveti a saját előzményeivel, és jelzi, ami nem illik bele. Minden mentés után a háttérben fut, és egyiket sem lassítja. A legtöbb ellenőrzés az elem 10 mentése után indul; a hibák, az adatok nagy részének újraírása és a majdnem üres forrás az elejétől ellenőrzött. A szabad helyet a helyi tárolóknál és azoknál az rclone tárolóknál figyeli, amelyek jelentik; az Unraid felhasználói megosztásán ez az egész tömb szabad helye.",
